function uniquePct(v,lang){let n=(v*100).toFixed(1);return (lang==='en'?n:n.replace('.',','))+' %';}
function uniqueBonusText(spec,lang='de'){let label=UNIQUE_BONUS_LABELS[spec.bonus]||UNIQUE_BONUS_LABELS.pctAtk;return '+'+uniquePct(spec.value,lang)+' '+(lang==='en'?label[1]:lang==='ru'?label[2]:label[0]);}
